use realm_agent::{model::*,strategy::*};
use std::collections::BTreeSet;
fn entity(id:u64,x:f32)->Entity{Entity{guid:id,kind:Kind::Player,entry:0,name:None,position:Some(Position{map:1,x,..Default::default()}),health:Some(100),max_health:Some(100),mana:Some(100),max_mana:Some(100),rage:Some(40),level:Some(60),class:None,form:None,flags:0,duel_arbiter:0,auras:BTreeSet::new(),target:None,updated_ms:0}}
fn world(class:u8,d:f32)->WorldView{let mut w=WorldView{class,self_guid:1,now_ms:100,position:entity(1,0.).position,..Default::default()};w.objects.insert(1,entity(1,0.));w.objects.insert(2,entity(2,d));w}
#[test]fn highest_known_uses_chain_not_id(){let mut w=world(8,20.);w.spells.extend([116,10181,25304]);assert!(matches!(choose(&w,2),Some(Action::Cast{spell:25304,..})));w.spells.remove(&25304);assert!(matches!(choose(&w,2),Some(Action::Cast{spell:10181,..})));w.cooldowns.insert(10181,10000);assert!(choose(&w,2).is_none());}
#[test]fn nova_then_finish_then_bolt(){let mut w=world(8,5.);w.spells.extend([10230,10199,25304]);assert!(matches!(choose(&w,2),Some(Action::Cast{spell:10230,target:None})));w.objects.get_mut(&2).unwrap().auras.insert(10230);w.objects.get_mut(&2).unwrap().health=Some(10);assert!(matches!(choose(&w,2),Some(Action::Cast{spell:10199,..})));}
#[test]fn mage_travel_is_standoff_candidate_and_no_cast_while_busy(){let mut w=world(8,60.);assert!(matches!(choose(&w,2),Some(Action::Navigate(p))if(p.x-36.).abs()<0.01));w.casting_until=500;assert!(choose(&w,2).is_none());}
#[test]fn warrior_swings_and_uses_learned_rank(){let mut w=world(1,2.);w.spells.insert(7373);let a=choose_actions(&w,2);assert!(matches!(a[0],Action::Attack(2)));assert!(matches!(a[1],Action::Cast{spell:7373,..}));w.objects.get_mut(&1).unwrap().rage=Some(0);assert_eq!(choose_actions(&w,2).len(),1);}
#[test]fn charge_requires_battle_stance_and_intercept_requires_combat(){let mut w=world(1,15.);w.spells.extend([2457,11578,2458,20617]);assert!(matches!(choose(&w,2),Some(Action::Cast{spell:2457,..})));w.objects.get_mut(&1).unwrap().auras.insert(2457);assert!(matches!(choose(&w,2),Some(Action::Cast{spell:11578,..})));w.objects.get_mut(&1).unwrap().flags=0x80000;assert!(matches!(choose(&w,2),Some(Action::Cast{spell:2458,..})));}
#[test]fn dead_or_absent_target_is_not_actionable(){let mut w=world(8,5.);w.spells.insert(116);w.objects.get_mut(&2).unwrap().health=Some(0);assert!(choose(&w,2).is_none());assert!(choose(&w,900).is_none());assert_eq!(spell_timing(25304),(3000,0,1500));assert_eq!(spell_timing(3567),(10000,0,1500));}
